properties.query:
// Security events via Legacy agent or Windows Security events via AMA
// ========= KQL =========
// version 0.3
// set the search term for the watchlist
// ===== customisation below =====
let search_name = dynamic(["security_events_via_legacy_agent", "window_security_events_via_ama"]);
let queryPeriod = ago(14d);
let LastEvent = (
    SecurityEvent
    // ===== customisation above =====
    | where TimeGenerated between (queryPeriod .. now())
    | summarize LastEvent = max(TimeGenerated)
);
let DecommissionedAssets = _GetWatchlist("connector_health_decommissioned_assets");
let watchlist_name  = "connector_health_wl_v1";
let safeline = datatable (SearchKey:string,lowerLimit:string )["","999h"];
// set the watch list to use
let connectorTables = materialize (_GetWatchlist(watchlist_name));
// select the entry from the watchlist, and merge in safeline, to prevent errors
let TSlowerLimit = toscalar(connectorTables 
    | where SearchKey in (search_name)
    | union safeline
    | project lowerLimit
    | extend  Timelowerlimit = totimespan(lowerLimit)
    // the line below will always pick the smaller of the entries - a real watchlist entry will always be below 999h
    | summarize min(Timelowerlimit)
);
LastEvent
// only show last event if it is greater than the limit pulled from the watchlist
| where LastEvent < ago(TSlowerLimit)
| extend QC_data_health_name = search_name, QC_data_health_type = "Connector Offline", QC_data_health_limit = TSlowerLimit
| project LastEvent,
    tostring(QC_data_health_name),
    QC_data_health_type,
    QC_data_health_limit
/////////////////////Handling decommissioned assets ////////////////////////// 
| join kind = leftouter DecommissionedAssets on $left.QC_data_health_name == $right.AssetName
| extend OfflineDate = todatetime(strcat_array(array_reverse(split(OfflineDate, "/")), "-"))
| where startofday(LastEvent) < startofday(OfflineDate)
  or isempty(OfflineDate)
